import{_ as s,o as c,a as e,b as l}from"./app.C41L12d5.js";const o=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"缓存控制","link":"/api/SIMD-API/c_api/cache_ctrl/cache_ctrl"},{"text":"asc_get_scalar_store_cache_mode","link":"/api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_store_cache_mode"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_store_cache_mode.md","filePath":"api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_store_cache_mode.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788435672000}'),n={name:"api/SIMD-API/c_api/cache_ctrl/asc_get_scalar_store_cache_mode.md"};function t(p,a,_,i,d,h){return c(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>asc_get_scalar_store_cache_mode</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/cache_ctrl/cache_ctrl.h&quot;</code>。</p><p>读取当前标量写（store）路径的L2 Cache管理策略，并返回<a href="../defs/enum/asc_store_l2_cache_mode.html">asc_store_l2_cache_mode</a>枚举值。</p><p>常用于临时切换策略前保存原配置，或在设置后做回读校验。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">asc_store_l2_cache_mode</span><span class="w"> </span><span class="n">asc_get_scalar_store_cache_mode</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>无</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>当前标量store路径的L2 Cache管理策略，类型为<a href="../defs/enum/asc_store_l2_cache_mode.html">asc_store_l2_cache_mode</a>。</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>本接口仅反映标量store侧策略，与标量load侧以及向量搬运接口参数中的<code>l2_cache_mode</code>无关。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>场景：与<a href="asc_set_scalar_cache_mode.html">asc_set_scalar_cache_mode</a>场景B一致。多核算子通过<a href="../atomic/scalar_atomic/asc_atomic_add.html">asc_atomic_add</a>向GM统计counter做标量原子累加；进入累加前查询并保存当前store策略，临时切换为<code>NOTALLOC_CLEAN</code>避免不必要的L2分配，累加结束后恢复原策略。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__gm__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">counter_gm</span><span class="p">;</span><span class="w">  </span><span class="c1">// GM上的多核共享计数器</span>

<span class="c1">// 查询并保存当前标量store策略</span>
<span class="n">asc_store_l2_cache_mode</span><span class="w"> </span><span class="n">old_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_get_scalar_store_cache_mode</span><span class="p">();</span>
<span class="c1">// 标量原子写GM控制字段，避免额外L2分配</span>
<span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">asc_store_l2_cache_mode</span><span class="o">::</span><span class="n">NOTALLOC_CLEAN</span><span class="p">);</span>

<span class="n">asc_dcci_entire_all</span><span class="p">();</span><span class="w">  </span><span class="c1">// 标量原子操作前保证DCache一致性</span>
<span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">counter_gm</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>

<span class="c1">// 恢复进入本段逻辑前的标量store策略</span>
<span class="n">asc_set_scalar_cache_mode</span><span class="p">(</span><span class="n">old_mode</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const v=s(n,[["render",t]]);export{o as __pageData,v as default};
